declare
  authorization_row public.continuous_intelligence_shadow_canary_manual_authorizations%rowtype;
  lease_row public.continuous_intelligence_shadow_canary_manual_execution_leases%rowtype;
  claim_row public.continuous_intelligence_shadow_canary_daily_claims%rowtype;
  authorization_found boolean := false;
  lease_found boolean := false;
  run_count integer;
  credit_count integer;
begin
  if p_utc_day is null or p_authorization_token is null or length(p_authorization_token) < 32 or p_execution_lease_id is null then
    return query select 'daily_usage_unavailable'::text, null::text, null::text, null::text, null::text;
    return;
  end if;

  perform pg_advisory_xact_lock(hashtext('continuous_intelligence_shadow_canary_manual_execution:' || p_utc_day::text));

  select * into authorization_row
  from public.continuous_intelligence_shadow_canary_manual_authorizations as authorization_table
  where authorization_table.authorization_id = p_authorization_id
  for update;
  authorization_found := found;
  select * into lease_row
  from public.continuous_intelligence_shadow_canary_manual_execution_leases as lease_table
  where lease_table.execution_lease_id = p_execution_lease_id
  for update;
  lease_found := found;

  if not authorization_found or not lease_found or authorization_row.authorization_id <> lease_row.authorization_id or
     authorization_row.request_fingerprint <> p_request_fingerprint or authorization_row.execution_id <> p_execution_id or
     authorization_row.claim_id <> p_claim_id or lease_row.request_fingerprint <> p_request_fingerprint or
     lease_row.execution_id <> p_execution_id or lease_row.claim_id <> p_claim_id or
     authorization_row.token_hash <> encode(digest(p_authorization_token, 'sha256'), 'hex') or
     authorization_row.ticker <> 'AAPL' or authorization_row.interval <> '5min' or
     authorization_row.requested_end - authorization_row.requested_start <> interval '30 minutes' or
     authorization_row.policy_total_credits <> 377 or authorization_row.policy_hard_reserve_credits <> 57 or
     authorization_row.policy_normal_planned_max_credits <> 320 or authorization_row.estimated_credits <> 1 or
     lease_row.ticker <> authorization_row.ticker or lease_row.interval <> authorization_row.interval or
     lease_row.requested_start <> authorization_row.requested_start or lease_row.requested_end <> authorization_row.requested_end or
     lease_row.policy_total_credits <> authorization_row.policy_total_credits or
     lease_row.policy_hard_reserve_credits <> authorization_row.policy_hard_reserve_credits or
     lease_row.policy_normal_planned_max_credits <> authorization_row.policy_normal_planned_max_credits or
     lease_row.estimated_credits <> authorization_row.estimated_credits then
    return query select 'identity_mismatch'::text, null::text, null::text, null::text, null::text;
    return;
  end if;

  if authorization_row.status = 'consumed' and lease_row.status = 'consumed' then
    select * into claim_row from public.continuous_intelligence_shadow_canary_daily_claims as claim_table
    where claim_table.claim_id = p_claim_id for update;
    if found and claim_row.execution_id = p_execution_id and claim_row.request_fingerprint = p_request_fingerprint then
      return query select 'already_admitted'::text, authorization_row.authorization_id, lease_row.execution_lease_id, claim_row.claim_id, claim_row.status;
    end if;
    return query select 'daily_usage_unavailable'::text, null::text, null::text, null::text, null::text;
    return;
  end if;
  if authorization_row.status <> 'issued' or lease_row.status <> 'issued' then
    return query select 'authorization_replayed'::text, null::text, null::text, null::text, null::text;
    return;
  end if;
  if authorization_row.expires_at <= now() or lease_row.expires_at <= now() then
    update public.continuous_intelligence_shadow_canary_manual_authorizations as authorization_table
      set status = 'expired' where authorization_table.authorization_id = authorization_row.authorization_id and authorization_table.status = 'issued';
    update public.continuous_intelligence_shadow_canary_manual_execution_leases as lease_table
      set status = 'expired' where lease_table.execution_lease_id = lease_row.execution_lease_id and lease_table.status = 'issued';
    return query select 'authorization_expired'::text, authorization_row.authorization_id, lease_row.execution_lease_id, null::text, null::text;
    return;
  end if;

  select count(*), coalesce(sum(estimated_credits), 0) into run_count, credit_count
  from public.continuous_intelligence_shadow_canary_daily_claims where utc_day = p_utc_day;
  if run_count >= 2 or credit_count + 1 > 2 then
    return query select 'daily_limit_reached'::text, authorization_row.authorization_id, lease_row.execution_lease_id, null::text, null::text;
    return;
  end if;

  insert into public.continuous_intelligence_shadow_canary_daily_claims (
    claim_id, execution_id, request_fingerprint, utc_day, estimated_credits, status, provider_attempted
  ) values (p_claim_id, p_execution_id, p_request_fingerprint, p_utc_day, 1, 'attempted', false);
  update public.continuous_intelligence_shadow_canary_manual_execution_leases as lease_table
    set status = 'consumed', consumed_at = now()
    where lease_table.execution_lease_id = lease_row.execution_lease_id and lease_table.status = 'issued';
  if not found then raise exception 'manual execution lease admission lost atomic state'; end if;
  update public.continuous_intelligence_shadow_canary_manual_authorizations as authorization_table
    set status = 'consumed', consumed_at = now()
    where authorization_table.authorization_id = authorization_row.authorization_id and authorization_table.status = 'issued';
  if not found then raise exception 'manual authorization admission lost atomic state'; end if;
  return query select 'attempt_started'::text, authorization_row.authorization_id, lease_row.execution_lease_id, p_claim_id, 'attempted'::text;
exception when unique_violation then
  return query select 'daily_usage_unavailable'::text, null::text, null::text, null::text, null::text;
end;

declare
  authorization_row public.continuous_intelligence_shadow_canary_manual_authorizations%rowtype;
  claim_row public.continuous_intelligence_shadow_canary_daily_claims%rowtype;
  run_count integer;
  credit_count integer;
begin
  if p_utc_day is null or p_authorization_token is null or length(p_authorization_token) < 32 then
    return query select 'daily_usage_unavailable'::text, null::text, null::text, null::text;
    return;
  end if;

  perform pg_advisory_xact_lock(hashtext('continuous_intelligence_shadow_canary_manual_execution:' || p_utc_day::text));

  select * into authorization_row
  from public.continuous_intelligence_shadow_canary_manual_authorizations
  where continuous_intelligence_shadow_canary_manual_authorizations.authorization_id = p_authorization_id
  for update;

  if not found or authorization_row.request_fingerprint <> p_request_fingerprint or
     authorization_row.execution_id <> p_execution_id or authorization_row.claim_id <> p_claim_id or
     authorization_row.token_hash <> encode(digest(p_authorization_token, 'sha256'), 'hex') then
    return query select 'identity_mismatch'::text, null::text, null::text, null::text;
    return;
  end if;

  if authorization_row.status = 'consumed' then
    select * into claim_row
    from public.continuous_intelligence_shadow_canary_daily_claims
    where continuous_intelligence_shadow_canary_daily_claims.claim_id = p_claim_id
    for update;
    if found and claim_row.execution_id = p_execution_id and claim_row.request_fingerprint = p_request_fingerprint then
      return query select 'already_admitted'::text, authorization_row.authorization_id, claim_row.claim_id, claim_row.status;
    end if;
    return query select 'daily_usage_unavailable'::text, null::text, null::text, null::text;
    return;
  end if;

  if authorization_row.status <> 'issued' then
    return query select 'authorization_replayed'::text, authorization_row.authorization_id, null::text, null::text;
    return;
  end if;
  if authorization_row.expires_at <= now() then
    update public.continuous_intelligence_shadow_canary_manual_authorizations
    set status = 'expired'
    where continuous_intelligence_shadow_canary_manual_authorizations.authorization_id = authorization_row.authorization_id;
    return query select 'authorization_expired'::text, authorization_row.authorization_id, null::text, null::text;
    return;
  end if;

  select count(*), coalesce(sum(estimated_credits), 0)
  into run_count, credit_count
  from public.continuous_intelligence_shadow_canary_daily_claims
  where utc_day = p_utc_day;
  if run_count >= 2 or credit_count + 1 > 2 then
    return query select 'daily_limit_reached'::text, authorization_row.authorization_id, null::text, null::text;
    return;
  end if;

  insert into public.continuous_intelligence_shadow_canary_daily_claims (
    claim_id, execution_id, request_fingerprint, utc_day, estimated_credits, status, provider_attempted
  ) values (
    p_claim_id, p_execution_id, p_request_fingerprint, p_utc_day, 1, 'attempted', false
  );

  update public.continuous_intelligence_shadow_canary_manual_authorizations
  set status = 'consumed', consumed_at = now()
  where continuous_intelligence_shadow_canary_manual_authorizations.authorization_id = authorization_row.authorization_id
    and continuous_intelligence_shadow_canary_manual_authorizations.status = 'issued';

  if not found then
    raise exception 'manual authorization admission lost atomic state';
  end if;

  return query select 'attempt_started'::text, authorization_row.authorization_id, p_claim_id, 'attempted'::text;
exception when unique_violation then
  return query select 'daily_usage_unavailable'::text, null::text, null::text, null::text;
end;

declare
  v_identity_key text := null;
begin
  if p_client_identity_digest is not null and p_client_identity_digest !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid_login_abuse_identity';
  end if;

  if p_client_identity_digest is not null then
    v_identity_key := 'client:' || p_client_identity_digest;
  end if;

  perform pg_advisory_xact_lock(hashtextextended('ture:login-abuse:global', 0));
  if v_identity_key is not null then
    perform pg_advisory_xact_lock(hashtextextended(v_identity_key, 0));
  end if;

  update public.application_login_abuse_buckets
  set failure_count = greatest(failure_count - 1, 0), updated_at = clock_timestamp()
  where bucket_key = 'global';

  if v_identity_key is not null then
    update public.application_login_abuse_buckets
    set failure_count = greatest(failure_count - 1, 0), updated_at = clock_timestamp()
    where bucket_key = v_identity_key;
  end if;

  return true;
end;

declare
  v_now timestamptz := clock_timestamp();
  v_global_failures integer := 0;
  v_global_expires_at timestamptz := v_now;
  v_identity_failures integer := 0;
  v_identity_expires_at timestamptz := v_now;
  v_retry_seconds integer := 0;
  v_identity_key text := null;
begin
  if p_client_identity_digest is not null and p_client_identity_digest !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid_login_abuse_identity';
  end if;

  if p_client_identity_digest is not null then
    v_identity_key := 'client:' || p_client_identity_digest;
  end if;

  perform pg_advisory_xact_lock(hashtextextended('ture:login-abuse:global', 0));
  if v_identity_key is not null then
    perform pg_advisory_xact_lock(hashtextextended(v_identity_key, 0));
  end if;

  delete from public.application_login_abuse_buckets
  where ctid in (
    select ctid
    from public.application_login_abuse_buckets
    where window_expires_at < v_now - interval '1 day'
    limit 100
  );

  select failure_count, window_expires_at
  into v_global_failures, v_global_expires_at
  from public.application_login_abuse_buckets
  where bucket_key = 'global'
  for update;

  if not found or v_global_expires_at <= v_now then
    v_global_failures := 0;
    v_global_expires_at := v_now + interval '15 minutes';
  end if;

  if v_identity_key is not null then
    select failure_count, window_expires_at
    into v_identity_failures, v_identity_expires_at
    from public.application_login_abuse_buckets
    where bucket_key = v_identity_key
    for update;

    if not found or v_identity_expires_at <= v_now then
      v_identity_failures := 0;
      v_identity_expires_at := v_now + interval '15 minutes';
    end if;
  end if;

  if v_global_failures >= 100 or v_identity_failures >= 5 then
    v_retry_seconds := greatest(
      1,
      ceil(extract(epoch from greatest(v_global_expires_at, v_identity_expires_at) - v_now))::integer
    );
    return query select false, v_retry_seconds, 'rate_limited'::text;
    return;
  end if;

  insert into public.application_login_abuse_buckets as bucket (
    bucket_key, failure_count, window_expires_at, updated_at
  ) values ('global', v_global_failures + 1, v_global_expires_at, v_now)
  on conflict (bucket_key) do update
  set failure_count = excluded.failure_count,
      window_expires_at = excluded.window_expires_at,
      updated_at = excluded.updated_at;

  if v_identity_key is not null then
    insert into public.application_login_abuse_buckets as bucket (
      bucket_key, failure_count, window_expires_at, updated_at
    ) values (v_identity_key, v_identity_failures + 1, v_identity_expires_at, v_now)
    on conflict (bucket_key) do update
    set failure_count = excluded.failure_count,
        window_expires_at = excluded.window_expires_at,
        updated_at = excluded.updated_at;
  end if;

  return query select true, 0, 'reserved'::text;
end;

declare
  v_recommendation public.recommendations%rowtype;
  v_existing_position public.positions%rowtype;
  v_existing_position_count integer;
  v_snapshot_link_count integer := 0;
  v_position_id uuid;
begin
  if p_command_version <> 'application_open_position_v1'
    or p_recommendation_id is null
    or p_ticker !~ '^[A-Z.]{1,16}$'
    or coalesce(length(p_company_name), 0) > 240
    or p_entry_price is null or p_entry_price <= 0
    or p_position_size is null or p_position_size <= 0
    or p_current_stop is null or p_current_stop <= 0
    or p_target_1 is null or p_target_1 <= 0
    or p_target_2 is null or p_target_2 <= 0
    or (p_execution_metadata is not null and jsonb_typeof(p_execution_metadata) <> 'object')
  then
    raise exception 'invalid_open_position_command';
  end if;

  select * into v_recommendation
  from public.recommendations
  where id = p_recommendation_id
  for update;

  if not found then
    raise exception 'recommendation_not_found';
  end if;

  if v_recommendation.ticker <> p_ticker
    or v_recommendation.status not in ('new', 'watched', 'taken')
  then
    raise exception 'recommendation_not_eligible_for_open_position';
  end if;

  select count(*) into v_existing_position_count
  from public.positions
  where recommendation_id = p_recommendation_id;

  if v_existing_position_count > 1 then
    raise exception 'recommendation_position_linkage_inconsistent';
  end if;

  if v_existing_position_count = 1 then
    select * into v_existing_position
    from public.positions
    where recommendation_id = p_recommendation_id
    for update;

    if v_existing_position.ticker is distinct from p_ticker
      or v_existing_position.company_name is distinct from p_company_name
      or v_existing_position.entry_price is distinct from p_entry_price
      or v_existing_position.position_size is distinct from p_position_size
      or v_existing_position.current_stop is distinct from p_current_stop
      or v_existing_position.target_1 is distinct from p_target_1
      or v_existing_position.target_2 is distinct from p_target_2
      or v_existing_position.execution_metadata is distinct from p_execution_metadata
      or v_existing_position.status is distinct from 'open'
      or v_recommendation.status is distinct from 'taken'
    then
      raise exception 'open_position_command_conflict';
    end if;

    v_position_id := v_existing_position.id;
    disposition := 'reused';
  else
    if v_recommendation.status = 'taken' then
      raise exception 'recommendation_taken_without_position';
    end if;

    insert into public.positions (
      recommendation_id,
      ticker,
      company_name,
      entry_price,
      position_size,
      current_stop,
      target_1,
      target_2,
      status,
      execution_metadata
    ) values (
      p_recommendation_id,
      p_ticker,
      p_company_name,
      p_entry_price,
      p_position_size,
      p_current_stop,
      p_target_1,
      p_target_2,
      'open',
      p_execution_metadata
    )
    returning id into v_position_id;

    update public.recommendations
    set status = 'taken'
    where id = p_recommendation_id;

    disposition := 'created';
  end if;

  if exists (
    select 1
    from public.recommendation_snapshots
    where recommendation_id = p_recommendation_id::text
      and linked_position_id is not null
      and linked_position_id <> v_position_id::text
  ) then
    raise exception 'recommendation_snapshot_linkage_conflict';
  end if;

  update public.recommendation_snapshots
  set status = 'taken',
      was_taken = true,
      linked_position_id = v_position_id::text,
      updated_at = now()
  where recommendation_id = p_recommendation_id::text;

  get diagnostics v_snapshot_link_count = row_count;

  position_id := v_position_id;
  snapshot_link_count := v_snapshot_link_count;
  return next;
end;

declare
  existing public.continuous_intelligence_shadow_canary_daily_claims%rowtype;
begin
  update public.continuous_intelligence_shadow_canary_daily_claims
  set status = 'attempted',
      provider_attempted = true
  where continuous_intelligence_shadow_canary_daily_claims.claim_id = p_claim_id
    and execution_id = p_execution_id
    and request_fingerprint = p_request_fingerprint
    and contract_version = p_expected_contract_version
    and status = 'claimed'
  returning * into existing;

  if found then
    return query select 'attempt_started'::text, existing.claim_id, existing.status;
    return;
  end if;

  select * into existing
  from public.continuous_intelligence_shadow_canary_daily_claims
  where continuous_intelligence_shadow_canary_daily_claims.claim_id = p_claim_id
  for update;

  if not found or
     existing.execution_id <> p_execution_id or
     existing.request_fingerprint <> p_request_fingerprint or
     existing.contract_version <> p_expected_contract_version then
    return query select 'daily_usage_unavailable'::text, null::text, null::text;
    return;
  end if;

  case existing.status
    when 'attempted' then
      return query select 'attempt_in_progress'::text, existing.claim_id, existing.status;
    when 'completed' then
      return query select 'already_completed'::text, existing.claim_id, existing.status;
    when 'failed' then
      return query select 'already_failed'::text, existing.claim_id, existing.status;
    else
      return query select 'daily_usage_unavailable'::text, null::text, null::text;
  end case;
end;

declare
  existing public.ci_hur_authorizations%rowtype;
  claim_row public.continuous_intelligence_shadow_canary_daily_claims%rowtype;
  source_audit public.bounded_shadow_collector_proof_audits%rowtype;
  legacy_ledger public.continuous_intelligence_credit_ledger%rowtype;
  ordinary_units smallint;
  reconciliation_count smallint;
  claim_capacity smallint;
begin
  if p_expires_at is null or p_issued_at is null or p_expires_at <= p_issued_at or p_expires_at > p_issued_at + interval '300 seconds' or
     p_expected_claim_capacity_units is distinct from 2 or p_expected_ordinary_ledger_units is distinct from 1 or
     p_expected_reconciliation_units is distinct from 0 or p_expected_missing_usage_units is distinct from 1 or
     p_authorization_id is null or length(p_authorization_id) not between 1 and 160 or
     not public.ci_hur_target_claim_id_allowed(p_target_claim_id) or
     p_source_audit_id is null or length(p_source_audit_id) not between 1 and 128 or
     p_reconciliation_identity is distinct from 'historical_manual_usage_reconciliation:continuous_intelligence_shadow_canary_historical_usage_reconciliation_v1:' || p_target_claim_id or
     p_evidence_digest is null or p_evidence_digest !~ '^[0-9a-f]{64}$' or
     p_requested_by is null or length(p_requested_by) not between 1 and 160 or
     p_deployment_commit is null or length(p_deployment_commit) not between 1 and 128 then
    return query select 'historical_state_malformed'::text, null::text, null::text;
    return;
  end if;
  perform pg_advisory_xact_lock(hashtext('ci_hur_authorization:' || p_target_claim_id));
  select * into existing from public.ci_hur_authorizations as authorization_row where authorization_row.authorization_id = p_authorization_id for update;
  if found then
    if existing.target_claim_id = p_target_claim_id and existing.reconciliation_identity = p_reconciliation_identity then
      return query select 'already_issued'::text, existing.authorization_id, existing.reconciliation_identity;
    end if;
    return query select 'authorization_target_mismatch'::text, null::text, null::text;
    return;
  end if;
  select * into claim_row from public.continuous_intelligence_shadow_canary_daily_claims as target_claim where target_claim.claim_id = p_target_claim_id for update;
  if not found then
    return query select 'target_claim_not_found'::text, null::text, null::text;
    return;
  end if;
  if claim_row.status <> 'completed' or claim_row.provider_attempted is not true or claim_row.source_receipt_id is null then
    return query select 'target_claim_not_completed'::text, null::text, null::text;
    return;
  end if;
  if not public.ci_hur_target_allowed(claim_row.claim_id, claim_row.execution_id, claim_row.source_receipt_id) then
    return query select 'target_claim_scope_mismatch'::text, null::text, null::text;
    return;
  end if;
  select * into source_audit from public.bounded_shadow_collector_proof_audits as matched_audit where matched_audit.receipt_id = p_source_audit_id and matched_audit.daily_claim_id = claim_row.claim_id for update;
  if not found then
    return query select 'source_audit_missing'::text, null::text, null::text;
    return;
  end if;
  if source_audit.entry_kind <> 'bounded_manual_proof' or source_audit.daily_claim_status <> 'completed' or
     source_audit.daily_claim_execution_id <> claim_row.execution_id or source_audit.provider_attempt_occurred is not true or
     source_audit.provider_request_count <> 1 or source_audit.receipt_id <> claim_row.source_receipt_id then
    return query select 'source_audit_mismatch'::text, null::text, null::text;
    return;
  end if;
  if not public.ci_hur_target_provider_result_allowed(claim_row.claim_id, claim_row.execution_id, claim_row.source_receipt_id, source_audit.primary_result_category) then
    return query select 'provider_usage_unverified'::text, null::text, null::text;
    return;
  end if;
  select * into legacy_ledger from public.continuous_intelligence_credit_ledger as legacy_entry where legacy_entry.source_receipt_id = claim_row.source_receipt_id for update;
  if not found or legacy_ledger.durable_audit_persisted is not false then
    return query select 'ledger_failure_evidence_mismatch'::text, null::text, null::text;
    return;
  end if;
  if legacy_ledger.generated_at = source_audit.generated_at then
    return query select 'ordinary_ledger_already_present'::text, null::text, null::text;
    return;
  end if;
  select count(*)::smallint into claim_capacity from public.continuous_intelligence_shadow_canary_daily_claims as day_claim where day_claim.utc_day = claim_row.utc_day;
  select coalesce(sum(ordinary_entry.provider_estimated_credits), 0)::smallint into ordinary_units from public.continuous_intelligence_credit_ledger as ordinary_entry where ordinary_entry.entry_kind = 'bounded_manual_proof' and ordinary_entry.generated_at >= claim_row.utc_day and ordinary_entry.generated_at < claim_row.utc_day + interval '1 day';
  select count(*)::smallint into reconciliation_count from public.ci_hur_reconciliations as existing_entry where existing_entry.historical_utc_day = claim_row.utc_day;
  if claim_capacity <> 2 or ordinary_units <> 1 or reconciliation_count <> 0 then
    return query select 'reconciliation_precondition_mismatch'::text, null::text, null::text;
    return;
  end if;
  insert into public.ci_hur_authorizations (authorization_id, target_claim_id, source_audit_id, reconciliation_identity, expected_claim_capacity_units, expected_ordinary_ledger_units, expected_reconciliation_units, expected_missing_usage_units, evidence_digest, requested_by, deployment_commit, issued_at, expires_at)
